INSERT INTO customer SELECT * REPLACE (c_custkey + 3000000000 AS c_custkey) FROM customer WHERE c_custkey IN (SELECT o_custkey FROM orders WHERE o_orderkey < 2147483648 AND o_orderkey % 8 = 0) AND NOT EXISTS (SELECT 1 FROM customer AS c WHERE c.c_custkey = customer.c_custkey + 3000000000);
INSERT INTO supplier SELECT * REPLACE (s_suppkey + 3000000000 AS s_suppkey) FROM supplier WHERE s_suppkey IN (SELECT l_suppkey FROM lineitem WHERE l_orderkey < 2147483648 AND l_orderkey % 8 = 0) AND NOT EXISTS (SELECT 1 FROM supplier AS c WHERE c.s_suppkey = supplier.s_suppkey + 3000000000);
INSERT INTO part SELECT * REPLACE (p_partkey + 3000000000 AS p_partkey) FROM part WHERE p_partkey IN (SELECT l_partkey FROM lineitem WHERE l_orderkey < 2147483648 AND l_orderkey % 8 = 0) AND NOT EXISTS (SELECT 1 FROM part AS c WHERE c.p_partkey = part.p_partkey + 3000000000);
INSERT INTO orders SELECT * REPLACE (o_orderkey + 3000000000 AS o_orderkey, o_custkey + 3000000000 AS o_custkey) FROM orders WHERE o_orderkey < 2147483648 AND o_orderkey % 8 = 0 AND NOT EXISTS (SELECT 1 FROM orders AS c WHERE c.o_orderkey = orders.o_orderkey + 3000000000);
INSERT INTO lineitem SELECT * REPLACE (l_orderkey + 3000000000 AS l_orderkey, l_partkey + 3000000000 AS l_partkey, l_suppkey + 3000000000 AS l_suppkey, l_extendedprice / (1 + (l_partkey + l_suppkey) % 5) AS l_extendedprice) FROM lineitem WHERE l_orderkey < 2147483648 AND l_orderkey % 8 = 0 AND NOT EXISTS (SELECT 1 FROM lineitem AS c WHERE c.l_orderkey = lineitem.l_orderkey + 3000000000 AND c.l_linenumber = lineitem.l_linenumber);
